/**
 * R7: Real cross-repository local Keycloak → PhiID → NBGPocketMesh smoke.
 *
 * Uses:
 *  1. A REAL disposable Keycloak OIDC account + PhiID BFF verified session
 *  2. A REAL signed PocketMesh permit generated by the reviewed, pinned repo
 *  3. An explicitly staged and acknowledged PhiID R6 approval signed by a
 *     distinct private key after the verified OIDC login
 *  4. A REAL one-shot PocketMesh child worker and its one-use nonce ledger
 *
 * Only the BUILT-IN SYNTHETIC PocketMesh network fixture is executed.
 * No production identity, remote service, untrusted code, or hardware probe.
 * Keycloak must already run on loopback using the disposable development realm.
 *
 * The installed pinned PocketMesh checkout is required at:
 *   integration/pocketmesh (see .github/workflows/keycloak-e2e.yml)
 */
import assert from 'node:assert/strict';
import {generateKeyPairSync} from 'node:crypto';
import {spawn,execFileSync} from 'node:child_process';
import {mkdtempSync,mkdirSync,writeFileSync,rmSync,readdirSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {
  ISSUER,ORIGIN,REDIRECT_URI
} from '../identity-lab/security.mjs';
import {
  CONFIG_SCHEMA as PHIID_APPROVAL_CONFIG_SCHEMA
} from '../identity-lab/pocket-approval.mjs';
import {
  waitForKeycloak,adminToken,adminJson,createDisposableUser,
  getKeycloakCode,appRequest,withBridge
} from './live-e2e.mjs';
import {createDemoLibrary} from '../../integration/pocketmesh/src/pocket-library.mjs';
import {
  prepareExecutionRequest,signExecutionRequest
} from '../../integration/pocketmesh/src/pocket-signed-gate.mjs';
import {CONFIG_SCHEMA as EXECUTOR_CONFIG_SCHEMA} from '../../integration/pocketmesh/src/pocket-executor-protocol.mjs';
import {
  APPROVAL_POLICY_SCHEMA,AUTHORIZED_REQUEST_SCHEMA,
  loadPhiIDApprovalPolicy,verifyPhiIDApproval,
  PHIID_LOOPBACK_DEV_ISSUER
} from '../../integration/pocketmesh/src/pocket-phiid-approval.mjs';

const EXPECTED_POCKETMESH_COMMIT='50d11cc7f28293c9f6e6333019dcb668fd299225';
const MESH_ROOT=fileURLToPath(new URL('../../integration/pocketmesh/',import.meta.url));
const WORKER=fileURLToPath(new URL('../../integration/pocketmesh/scripts/pocket-phiid-executor-worker.mjs',import.meta.url));

if(process.env.PHIID_E2E_ENABLE!=='1'||
   process.env.PHIID_POCKET_E2E_ENABLE!=='1'||
   process.env.NODE_ENV==='production'){
  throw new Error('Explicit disposable localhost-only PocketMesh E2E opt-in required');
}
assert.equal(ISSUER,PHIID_LOOPBACK_DEV_ISSUER,'PhiID and PocketMesh local issuer contracts differ');
assert.equal(
  execFileSync('git',['rev-parse','HEAD'],{cwd:MESH_ROOT,encoding:'utf8'}).trim(),
  EXPECTED_POCKETMESH_COMMIT,
  'PocketMesh integration checkout is not at the audited pinned commit'
);

function createFixture(subject){
  const root=mkdtempSync(join(tmpdir(),'phiid-pocket-real-e2e-'));
  const ledgerDir=join(root,'spent');
  mkdirSync(ledgerDir,{mode:0o700});
  const permitSigner=generateKeyPairSync('ed25519');
  const approvalSigner=generateKeyPairSync('ed25519');
  const keyFile=join(root,'approver-private.pem');
  writeFileSync(keyFile,approvalSigner.privateKey.export({format:'pem',type:'pkcs8'}),
    {mode:0o600,flag:'wx'});
  const phiidConfigFile=join(root,'phiid-approval.json');
  writeFileSync(phiidConfigFile,JSON.stringify({
    schema:PHIID_APPROVAL_CONFIG_SCHEMA,
    policyEpoch:1,approvalKeyId:'approval-ci',permitKeyId:'permit-ci',
    permitPublicKeyPem:permitSigner.publicKey.export({format:'pem',type:'spki'}),
    approvalPrivateKeyFile:keyFile,allowedSubjects:[subject],
    allowedProfiles:['health']
  }),{mode:0o600,flag:'wx'});
  const executorFile=join(root,'pocket-executor.json');
  writeFileSync(executorFile,JSON.stringify({
    schema:EXECUTOR_CONFIG_SCHEMA,ledgerDir,
    allowedProfiles:['health'],
    trustedKeys:{'permit-ci':permitSigner.publicKey.export({format:'pem',type:'spki'})}
  }),{mode:0o600,flag:'wx'});
  const approvalPolicyFile=join(root,'pocket-approval-policy.json');
  writeFileSync(approvalPolicyFile,JSON.stringify({
    schema:APPROVAL_POLICY_SCHEMA,policyEpoch:1,
    allowedSubjects:[{iss:ISSUER,sub:subject}],revokedApprovalIds:[],
    trustedApprovers:{'approval-ci':approvalSigner.publicKey.export({format:'pem',type:'spki'})}
  }),{mode:0o600,flag:'wx'});
  return {
    root,ledgerDir,permitSigner,phiidConfigFile,executorFile,approvalPolicyFile,
    cleanup:()=>rmSync(root,{recursive:true,force:true})
  };
}
function childWorker(envelope,fixture){
  return new Promise((resolveWorker,reject)=>{
    const child=spawn(process.execPath,
      [WORKER,fixture.executorFile,fixture.approvalPolicyFile],
      {stdio:['pipe','pipe','pipe'],env:{...process.env,NODE_OPTIONS:''}}
    );
    let stdout='',stderr='';
    child.stdout.on('data',b=>{
      stdout+=b.toString('utf8');
      if(stdout.length>16384)child.kill();
    });
    child.stderr.on('data',b=>{
      // Never disclose potentially sensitive process stderr in CI logs.
      stderr+=b.toString('utf8').slice(0,512);
    });
    child.on('error',reject);
    child.on('close',code=>{
      try {
        const lines=stdout.trim().split('\n');
        assert.equal(lines.length,1,'Pocket worker emitted more than one response');
        resolveWorker({code,reply:JSON.parse(lines[0]),stderrPresent:stderr.length>0});
      }catch(e){reject(e);}
    });
    child.stdin.on('error',()=>{});
    child.stdin.end(JSON.stringify(envelope));
  });
}
const jsonBody=async res=>res.json();

async function exerciseRealSessionAndWorker(user,fixture){
  const noSession=await appRequest('/auth/session');
  assert.equal((await jsonBody(noSession)).authenticated,false);

  // First issue a signed permit from the ACTUAL pinned PocketMesh runner.
  const library=createDemoLibrary();
  const request=await prepareExecutionRequest({library,profile:'health'});
  assert.equal(request.albumId,'network-health');
  assert.equal(request.profile,'health');
  assert.equal(request.librarySha256,library.librarySha256);
  const permit=signExecutionRequest(request,{
    keyId:'permit-ci',privateKey:fixture.permitSigner.privateKey
  });

  // No ordinary PhiID profile-sharing consent can authorize execution.
  const r2Shape={
    schema:'phiid.local-consent-receipt/0.1',
    authority_granted:false,status:'recorded_not_enforced'
  };
  const noConsentGrant=await childWorker({
    schema:AUTHORIZED_REQUEST_SCHEMA,permit,approval:r2Shape
  },fixture);
  assert.equal(noConsentGrant.reply.status,'REFUSE');
  assert.equal(readdirSync(fixture.ledgerDir).length,0);

  // Real OIDC flow through the running PhiID BFF. Credentials go ONLY to
  // Keycloak's own localhost login form, as in R4; never to PocketMesh.
  const start=await appRequest('/auth/login');
  assert.equal(start.status,302);
  const cookie=start.headers.get('set-cookie')?.split(';',1)[0];
  assert.match(cookie||'',/^phiid_flow=[A-Za-z0-9_-]{40,}/);
  const callback=await getKeycloakCode(start.headers.get('location'),REDIRECT_URI,user);
  const signedIn=await appRequest(callback.pathname+callback.search,{cookie});
  assert.equal(signedIn.status,302);
  const localCookie=(signedIn.headers.getSetCookie?.()||[])
    .find(x=>x.startsWith('phiid_session='))?.split(';',1)[0];
  assert.match(localCookie||'',/^phiid_session=[A-Za-z0-9_-]{40,}/);
  const sessionResult=await appRequest('/auth/session',{cookie:localCookie});
  const profile=await jsonBody(sessionResult);
  assert.equal(profile.authenticated,true);
  assert.equal(profile.issuer,ISSUER);
  assert.equal(profile.sub,user.userId);
  assert.ok(!Object.hasOwn(profile,'access_token'));
  assert.ok(!Object.hasOwn(profile,'refresh_token'));

  const status=await appRequest('/auth/pocket/status',{cookie:localCookie});
  const flags=await jsonBody(status);
  assert.equal(flags.enabled,true);
  assert.equal(flags.permitted,true);
  assert.equal(flags.executionsPerformed,false);

  // The verified session is necessary, but not sufficient.
  const anonymousReview=await appRequest('/auth/pocket/review',{
    method:'POST',action:'pocket-review',body:{permit}
  });
  assert.equal(anonymousReview.status,401);
  const missingOrigin=await appRequest('/auth/pocket/review',{
    method:'POST',cookie:localCookie,body:{permit}
  });
  assert.equal(missingOrigin.status,403);
  const mutatedPermit={...permit,request:{...permit.request,albumId:'unknown-album'}};
  const tamperedReview=await appRequest('/auth/pocket/review',{
    method:'POST',cookie:localCookie,action:'pocket-review',
    body:{permit:mutatedPermit}
  });
  assert.equal(tamperedReview.status,400);

  const reviewResponse=await appRequest('/auth/pocket/review',{
    method:'POST',cookie:localCookie,action:'pocket-review',body:{permit}
  });
  assert.equal(reviewResponse.status,200,'genuine signed PocketMesh permit was not accepted');
  const review=await jsonBody(reviewResponse);
  assert.equal(review.details.albumId,request.albumId);
  assert.equal(review.details.revision,request.albumRevision);
  assert.equal(review.details.mode,request.mode);
  assert.equal(review.details.scope,'pocket.album.execute');

  const noAck=await appRequest('/auth/pocket/approve',{
    method:'POST',cookie:localCookie,action:'pocket-approve',
    body:{reviewId:review.reviewId,acknowledged:false}
  });
  assert.equal(noAck.status,400,'approval without explicit acknowledgement was allowed');

  const approvalResponse=await appRequest('/auth/pocket/approve',{
    method:'POST',cookie:localCookie,action:'pocket-approve',
    body:{reviewId:review.reviewId,acknowledged:true}
  });
  assert.equal(approvalResponse.status,200,'verified session did not produce approval');
  const envelope=await jsonBody(approvalResponse);
  assert.equal(envelope.schema,AUTHORIZED_REQUEST_SCHEMA);
  assert.deepEqual(envelope.permit,permit);
  assert.equal(envelope.approval.statement.subject.iss,ISSUER);
  assert.equal(envelope.approval.statement.subject.sub,user.userId);

  const expiredReview=await appRequest('/auth/pocket/approve',{
    method:'POST',cookie:localCookie,action:'pocket-approve',
    body:{reviewId:review.reviewId,acknowledged:true}
  });
  assert.equal(expiredReview.status,400,'same review signed twice');

  // Verify the actual returned PhiID signature with the actual pinned
  // PocketMesh approval-verifier, not a second copy of mock verification.
  const policy=loadPhiIDApprovalPolicy(fixture.approvalPolicyFile);
  const approved=verifyPhiIDApproval({
    permit:envelope.permit,approval:envelope.approval,policy,
    executorTrustRoots:{'permit-ci':fixture.permitSigner.publicKey}
  });
  assert.match(approved.principalSha256,/^[a-f0-9]{64}$/);
  assert.equal(readdirSync(fixture.ledgerDir).length,0,
    'review/signing itself may not execute a Pocket Album');

  // An altered approval must refuse WITHOUT spending the permit.
  const wrongApproval={
    ...envelope,approval:{
      ...envelope.approval,statement:{
        ...envelope.approval.statement,
        subject:{iss:ISSUER,sub:'forged-disposable-user'}
      }
    }
  };
  const attack=await childWorker(wrongApproval,fixture);
  assert.equal(attack.reply.status,'REFUSE');
  assert.equal(readdirSync(fixture.ledgerDir).length,0);

  // The real PocketMesh child executes the one trusted synthetic album.
  const executed=await childWorker(envelope,fixture);
  assert.equal(executed.code,0);
  assert.equal(executed.reply.status,'PERFORM');
  assert.match(executed.reply.receiptSha256,/^[a-f0-9]{64}$/);
  assert.match(executed.reply.outputSha256,/^[a-f0-9]{64}$/);
  assert.equal(executed.reply.principalSha256,approved.principalSha256);
  assert.equal(readdirSync(fixture.ledgerDir).length,1);
  assert.ok(!Object.hasOwn(executed.reply,'output'));
  assert.doesNotMatch(JSON.stringify(executed.reply),/switch-fixture|eth1|critical|access_token|phiid_session/);

  const replay=await childWorker(envelope,fixture);
  assert.equal(replay.reply.status,'REFUSE');
  assert.notEqual(replay.code,0);
  assert.equal(readdirSync(fixture.ledgerDir).length,1);

  // Session cleanup does not retroactively make expired/replayed approvals
  // valid; the permit already spent its nonce.
  const logout=await appRequest('/auth/logout',{
    method:'POST',cookie:localCookie,action:'logout'
  });
  assert.equal(logout.status,200);
  assert.equal((await (await appRequest('/auth/session',{cookie:localCookie})).json()).authenticated,false);

  return {
    permitPrepared:true,realOidcSubjectMatched:true,
    explicitApprovalRequired:true,phiidApprovalSignatureVerified:true,
    pocketWorkerDecision:executed.reply.status,
    crossProcessReplayDenied:true,r2ConsentRejected:true
  };
}

async function main(){
  await waitForKeycloak();
  const admin=await adminToken();
  let user,fixture;
  try{
    user=await createDisposableUser(admin);
    fixture=createFixture(user.userId);
    process.env.PHIID_POCKET_APPROVAL_CONFIG=fixture.phiidConfigFile;
    const result=await withBridge(()=>exerciseRealSessionAndWorker(user,fixture));
    assert.equal(result.pocketWorkerDecision,'PERFORM');
    console.log('PASS: real disposable Keycloak OIDC session → explicit PhiID approval → pinned PocketMesh one-shot execution → replay REFUSE');
    console.log('BOUNDARY: reviewed synthetic network fixture only; no live OS, network device, account or production permissions');
  }finally{
    delete process.env.PHIID_POCKET_APPROVAL_CONFIG;
    if(fixture)fixture.cleanup();
    if(user?.userId){
      const deleted=await adminJson(admin,'/admin/realms/phiid-dev/users/'+user.userId,{method:'DELETE'});
      assert.equal(deleted.status,204,'disposable Keycloak user cleanup failed');
    }
  }
}

await main().catch(err=>{
  // Never log Keycloak credentials, token contents, callback URLs,
  // session cookies, user ID or signed envelopes in CI.
  console.error('PhiID ↔ PocketMesh real-local E2E FAILED:',err?.name||'Error',
    err?.name==='AssertionError'?String(err.message).slice(0,130):'inspect controlled test step');
  process.exitCode=1;
});
